"""
Pure editor-time cell contour extraction; rejects holes/disconnected
outlines.
"""

import math
from collections.abc import Sequence
from typing import TypeVar

# Exact mesh outlines consume the boundary generated by the native extractor.
MAX_MESH_BOUNDARY_EDGES = 8192
MAX_OUTLINE_VALIDATION_POINTS = 2048
Point = TypeVar("Point", bound=Sequence[float])
Point3 = tuple[float, float, float]


def simplify(points: list[Point], tolerance: float) -> list[Point]:
    if len(points) < 3:
        return points
    kept = [0]
    ranges = [(0, len(points) - 1)]
    while ranges:
        start, end = ranges.pop()
        if end - start < 2:
            kept.append(end)
            continue
        a = points[start]
        delta = [b - origin for origin, b in zip(a, points[end])]
        length_squared = sum(d * d for d in delta)
        farthest = tolerance
        split = None
        for index in range(start + 1, end):
            offset = [p - origin for p, origin in zip(points[index], a)]
            t = 0
            if length_squared:
                projection = sum(p * d for p, d in zip(offset, delta))
                t = max(0, min(1, projection / length_squared))
            distance = math.hypot(*(p - t * d for p, d in zip(offset, delta)))
            if distance > farthest:
                farthest, split = distance, index
        if split is None:
            kept.append(end)
        else:
            ranges.append((split, end))
            ranges.append((start, split))
    return [points[index] for index in kept]


def _exterior_loop(occupied):
    edges = set()
    for x, y in occupied:
        corners = [(x, y), (x + 1, y), (x + 1, y + 1), (x, y + 1)]
        for a, b in zip(corners, corners[1:] + corners[:1]):
            if (b, a) in edges:
                edges.remove((b, a))
            else:
                edges.add((a, b))
    following = {}
    for a, b in edges:
        if a in following:
            raise ValueError(
                "Surface touches only at a corner; split or repair the "
                "selected water surface"
            )
        following[a] = b
    loops = []
    while following:
        start = min(following)
        cursor = start
        loop = []
        while True:
            loop.append(cursor)
            if cursor not in following:
                raise ValueError("Open surface outline")
            cursor = following.pop(cursor)
            if cursor == start:
                break
        loops.append(loop)
    if len(loops) != 1:
        raise ValueError(
            "Selected surface has holes or disconnected pieces. Use separate "
            "simple splines or keep Grid Area; no holes will be silently "
            "filled."
        )
    return loops[0]


def lake_outline(
    cells: Sequence[Point3],
    step: float,
    tolerance: float = 30,
    max_points: int = 256,
) -> list[Point3]:
    if not cells or not math.isfinite(step) or step <= 0:
        raise ValueError("Invalid surface cells")
    if not math.isfinite(tolerance) or tolerance < 0:
        raise ValueError("Invalid simplify tolerance")
    if max(p[2] for p in cells) - min(p[2] for p in cells) > 1:
        raise ValueError(
            "Lake surface must be horizontal; use Line for sloped water"
        )
    minx = min(p[0] for p in cells)
    miny = min(p[1] for p in cells)
    occupied = {
        (round((p[0] - minx) / step), round((p[1] - miny) / step))
        for p in cells
    }
    loop = _exterior_loop(occupied)
    points = [
        (minx + (x - 0.5) * step, miny + (y - 0.5) * step) for x, y in loop
    ]
    # Remove collinear samples before RDP to reduce its search ranges.
    points = [
        p
        for i, p in enumerate(points)
        if (p[0] - points[i - 1][0])
        * (points[(i + 1) % len(points)][1] - p[1])
        != (p[1] - points[i - 1][1])
        * (points[(i + 1) % len(points)][0] - p[0])
    ]
    split = max(
        range(1, len(points)), key=lambda i: math.dist(points[0], points[i])
    )
    result = (
        simplify(points[: split + 1], tolerance)[:-1]
        + simplify(points[split:] + points[:1], tolerance)[:-1]
    )
    if not 3 <= len(result) <= max_points:
        raise ValueError(
            f"Outline needs 3–{max_points} points; increase simplification "
            f"tolerance or split the surface"
        )
    return [(x, y, cells[0][2]) for x, y in result]


def simplify_path(
    points: list[Point], tolerance: float, closed: bool = False
) -> list[Point]:
    """RDP in 3D; preserves open endpoints and the closed seam."""

    if not closed:
        return simplify(points, tolerance)
    split = max(
        range(1, len(points)), key=lambda i: math.dist(points[0], points[i])
    )
    first = simplify(points[: split + 1], tolerance)
    last = simplify(points[split:] + points[:1], tolerance)
    return first[:-1] + last[:-1]


def mesh_outline(edges, tolerance=30, max_points=MAX_MESH_BOUNDARY_EDGES):
    """
    Order one exact welded mesh boundary; never replace concavities with a
    hull.
    """
    if not math.isfinite(tolerance) or tolerance < 0:
        raise ValueError("Invalid simplify tolerance")
    if not 3 <= len(edges) <= MAX_MESH_BOUNDARY_EDGES:
        raise ValueError("Invalid mesh boundary edge count")
    adjacent = {}
    for a, b in edges:
        a = tuple(a)
        b = tuple(b)
        if (
            len(a) != 3
            or len(b) != 3
            or not all(math.isfinite(v) for v in a + b)
            or a == b
        ):
            raise ValueError("Invalid mesh edge")
        adjacent.setdefault(a, set()).add(b)
        adjacent.setdefault(b, set()).add(a)
    if any(len(neighbors) != 2 for neighbors in adjacent.values()):
        raise ValueError(
            "Mesh outline branches or is open; select a clean water sheet"
        )
    start = min(adjacent)
    points = [start]
    previous = start
    cursor = min(adjacent[start])
    while cursor != start:
        if len(points) >= len(adjacent):
            raise ValueError("Invalid mesh loop")
        points.append(cursor)
        following = next(p for p in adjacent[cursor] if p != previous)
        previous, cursor = cursor, following
    if len(points) != len(adjacent):
        raise ValueError(
            "Water has holes or disconnected pieces; use separate simple "
            "splines"
        )
    if max(p[2] for p in points) - min(p[2] for p in points) > 1:
        raise ValueError("Lake must be horizontal")
    result = simplify_path(points, tolerance, True)
    if not 3 <= len(result) <= max_points:
        raise ValueError(
            "Outline collapsed or exceeds point budget; adjust tolerance"
        )
    # Detect crossings introduced by aggressive simplification (or overlapping
    # source meshes).
    validate_simple_outline(result)
    return result


def validate_simple_outline(points: Sequence[Sequence[float]]) -> None:
    def turn(a, b, c):
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

    def on_segment(a, b, c):
        return (
            min(a[0], b[0]) - 1e-7 <= c[0] <= max(a[0], b[0]) + 1e-7
            and min(a[1], b[1]) - 1e-7 <= c[1] <= max(a[1], b[1]) + 1e-7
        )

    if len(points) > MAX_OUTLINE_VALIDATION_POINTS:
        raise ValueError(
            "Outline too detailed for topology validation; increase "
            "simplification tolerance"
        )
    for i, a in enumerate(points):
        b = points[(i + 1) % len(points)]
        for j in range(i + 2, len(points)):
            if i == 0 and j == len(points) - 1:
                continue
            c = points[j]
            d = points[(j + 1) % len(points)]
            if (
                max(a[0], b[0]) < min(c[0], d[0])
                or max(c[0], d[0]) < min(a[0], b[0])
                or max(a[1], b[1]) < min(c[1], d[1])
                or max(c[1], d[1]) < min(a[1], b[1])
            ):
                continue
            values = (
                turn(a, b, c),
                turn(a, b, d),
                turn(c, d, a),
                turn(c, d, b),
            )
            if (
                values[0] * values[1] < 0 and values[2] * values[3] < 0
            ) or any(
                abs(v) < 1e-7 and on_segment(x, y, z)
                for v, x, y, z in zip(
                    values, (a, a, c, c), (b, b, d, d), (c, d, a, b)
                )
            ):
                raise ValueError(
                    "Outline intersects itself; reduce tolerance or repair "
                    "the source water sheet"
                )
